async ({ workspace: { read, search, glob }, git: { status, log } }) => {
  const [skill, refs, rel, st, lg] = await Promise.all([
    read(".pi/skills/pit-delivery/SKILL.md", { format: "raw" }),
    search("Run independent calls together", { limit: 50, contextLines: 0 }),
    glob([".pi/skills/**/*.md", "docs/**/release*", "RELEASING*", "CHANGELOG*", ".github/workflows/*"]),
    status(["--short", "--branch"]),
    log(["--oneline", "-8"]),
  ]);
  return { skill: skill.content, refs: refs.matches.map((m) => `${m.file}:${m.line}`), rel: rel.entries, st: st.stdout, lg: lg.stdout };
}
